// Build the GoHighLevel payload from a site_visits row.
// Triggered by a Supabase database webhook on insert/update of site_visits.

const SIGNED_URL_TTL = 60 * 60 * 24 * 365 * 5; // 5 years — Terry clicks these long after the job

const SUPABASE_URL = $env.SUPABASE_URL;
const KEY = $env.SUPABASE_SERVICE_ROLE_KEY;
const hdr = { apikey: KEY, Authorization: `Bearer ${KEY}`, 'Content-Type': 'application/json' };

const body = $input.first().json.body || $input.first().json;
const visit = body.record || body;

if (!visit || !visit.id) throw new Error('No site_visits record in webhook payload');

// Pull the job and installer this visit belongs to.
const [job] = await this.helpers.httpRequest({
  method: 'GET',
  url: `${SUPABASE_URL}/rest/v1/jobs?id=eq.${visit.job_id}&select=*`,
  headers: hdr, json: true,
});
const [installer] = await this.helpers.httpRequest({
  method: 'GET',
  url: `${SUPABASE_URL}/rest/v1/installers?id=eq.${visit.installer_id}&select=full_name,ghl_user_id`,
  headers: hdr, json: true,
});

// Long-lived signed URLs for the photos. The bucket stays private.
async function sign(path) {
  if (!path) return null;
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: `${SUPABASE_URL}/storage/v1/object/sign/site-photos/${path}`,
    headers: hdr,
    body: { expiresIn: SIGNED_URL_TTL },
    json: true,
  });
  return res?.signedURL ? `${SUPABASE_URL}/storage/v1${res.signedURL}` : null;
}
const signFn = sign.bind(this);

const selfie = await signFn(visit.clockin_photo_path);
const completed = await signFn(visit.clockout_photo_path);

// Formatting. GoHighLevel has no duration type, so time_on_site is a string.
const syd = (iso) => iso ? new Date(iso).toLocaleString('en-AU', {
  timeZone: 'Australia/Sydney', day: 'numeric', month: 'short',
  hour: 'numeric', minute: '2-digit', hour12: true }) : null;

const mins = visit.duration_minutes;
const durationHuman = mins == null ? '' : `${Math.floor(mins/60)}h ${String(mins%60).padStart(2,'0')}m`;

const suburb = (job?.address || '').split(',').slice(-2)[0]?.trim() || '';
const dateShort = visit.clockin_at
  ? new Date(visit.clockin_at).toLocaleDateString('en-AU', { timeZone: 'Australia/Sydney', day: 'numeric', month: 'short' })
  : '';

const isClockOut = !!visit.clockout_at;
const distance = visit.clockin_distance_m == null ? null : Math.round(visit.clockin_distance_m);

return [{
  json: {
    visit_id: visit.id,
    ghl_record_id: visit.ghl_record_id || null,
    is_clock_out: isClockOut,
    ghl_contact_id: job?.ghl_contact_id || null,
    ghl_user_id: installer?.ghl_user_id || null,
    record: {
      visit_label: `${installer?.full_name || 'Unknown'} — ${dateShort}${suburb ? ', ' + suburb : ''}`,
      installer_name: installer?.full_name || 'Unknown',
      ghl_appointment_id: job?.ghl_appointment_id || '',
      clockin_time: visit.clockin_at,
      clockout_time: visit.clockout_at,
      time_on_site: durationHuman,
      clockin_coords: `${visit.clockin_lat}, ${visit.clockin_lng}`,
      distance_from_job_m: distance,
      gps_accuracy_m: visit.clockin_accuracy_m == null ? null : Math.round(visit.clockin_accuracy_m),
      map_link: `https://maps.google.com/?q=${visit.clockin_lat},${visit.clockin_lng}`,
      selfie_url: selfie,
      completed_work_url: completed,
      status: isClockOut ? 'Complete' : 'On site',
    },
    note_body: isClockOut
      ? `${installer?.full_name} clocked out ${syd(visit.clockout_at)}. On site ${durationHuman}.\nCompleted work: ${completed || 'no photo'}`
      : `${installer?.full_name} clocked in ${syd(visit.clockin_at)}${distance != null ? `, ${distance} m from site` : ''}.\nPhoto: ${selfie || 'no photo'}`,
  },
}];
